def process(rawsStations) -> pd.DataFrame:
    import pandas as pd

    # Coerce candidate ID columns to numeric (some may contain NaN)
    df = rawsStations.copy()
    for col in ['Station ID', 'WX ID', 'NESS ID', 'NWS ID', 'MesoWest Station ID']:
        if col in df.columns:
            if col in ['NESS ID', 'NWS ID', 'MesoWest Station ID']:
                df[col + ' (str)'] = df[col].astype('string')
            df[col + ' (num)'] = pd.to_numeric(df[col], errors='coerce')

    out = []
    for col in ['Station ID (num)', 'WX ID (num)', 'NESS ID (num)', 'NWS ID (num)', 'MesoWest Station ID (num)']:
        if col in df.columns:
            s = df[col]
            out.append({
                'col': col,
                'count': int(s.shape[0]),
                'nonNull': int(s.notna().sum()),
                'nunique': int(s.nunique(dropna=True)),
                'min': float(s.min()) if s.notna().any() else None,
                'max': float(s.max()) if s.notna().any() else None,
                'example_vals': ', '.join(map(lambda x: str(int(x)) if pd.notna(x) else 'NA', s.dropna().unique()[:10]))
            })

    return pd.DataFrame(out)
